256	        // 历史：1 条暂停（轮次1）+ 1 条恢复（新轮次2，含原因与 UTC 时刻）
257	        MvcResult history = mockMvc.perform(get("/api/releases/" + releaseId + "/history"))
258	                .andExpect(jsonPath("$.pauses.length()").value(1))
259	                .andExpect(jsonPath("$.pauses[0].monitorRound").value(1))
